import bpy,json,numpy as np
from pathlib import Path
R=Path(__file__).resolve().parent;out=R/'seam-study-r10-maps';s=bpy.context.scene;s.view_settings.view_transform='Raw';s.view_settings.look='None';s.view_settings.exposure=0;s.view_settings.gamma=1;s.render.image_settings.file_format='JPEG';s.render.image_settings.color_mode='RGB';s.render.image_settings.quality=95
img=bpy.data.images.load(str(out/'fine-calf-roughness-2k.png'));img.colorspace_settings.name='Non-Color';img.save_render(str(out/'fine-calf-roughness-2k-runtime.jpg'),scene=s)
a=np.array(img.pixels[:],dtype=np.float32).reshape(-1,4)[:,:3];jpg=bpy.data.images.load(str(out/'fine-calf-roughness-2k-runtime.jpg'));jpg.colorspace_settings.name='Non-Color';b=np.array(jpg.pixels[:],dtype=np.float32).reshape(-1,4)[:,:3];err=np.abs(a-b);report={'source_range':[float(a.min()),float(a.max())],'jpeg_range':[float(b.min()),float(b.max())],'mae':float(err.mean()),'max_error':float(err.max()),'jpeg_bytes':(out/'fine-calf-roughness-2k-runtime.jpg').stat().st_size,'encoder':'Blender JPEG95, Raw view transform, Non-Color; original PNG unchanged'};print(report,flush=True);(R/'seam-study-roughness-compression-audit.json').write_text(json.dumps(report,indent=2));assert report['mae']<.004
